import net from 'node:net';
export function whoisRequest(domain){return new Promise(resolve=>{const host=domain.endsWith('.ir')?'whois.nic.ir':'whois.verisign-grs.com';let text='',done=false;const socket=net.createConnection({host,port:43});const finish=value=>{if(done)return;done=true;socket.destroy();resolve(value)};const timer=setTimeout(()=>finish(''),6000);socket.on('connect',()=>socket.write(domain+'\r\n'));socket.on('data',chunk=>{text+=chunk.toString('utf8');if(text.length>65536)finish('')});socket.on('end',()=>finish(text));socket.on('error',()=>finish(''));socket.on('close',()=>clearTimeout(timer));});}
export async function lookupWithWhois(domain,primary,whois=whoisRequest){const result=await primary(domain);if(result.status!=='unknown')return result;try{const text=await whois(domain),escaped=domain.replaceAll('.','\\.');if(new RegExp('(?:domain name|domain|ascii):\\s*'+escaped+'(?:\\s|$)','i').test(text))return {status:'registered',source:'whois'};if(domain.endsWith('.ir')?/no entries found/i.test(text):new RegExp('No match for "'+escaped+'"','i').test(text))return {status:'unregistered',source:'whois'};}catch{}return {status:'unknown'};}
